package org.apache.commons.math3.optim.nonlinear.vector;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math3.linear.DiagonalMatrix;
import org.apache.commons.math3.linear.MatrixUtils;
import org.apache.commons.math3.linear.NonSquareMatrixException;
import org.apache.commons.math3.linear.RealMatrix;
import org.apache.commons.math3.optim.OptimizationData;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for Weight constructor and getter.
 */
public class Weight_Weight_TriageGen0Test {

    @Test
    public void testWeightConstructorWithArray() {
        double[] weightArray = {1.0, 2.5, 3.0};
        Weight weight = new Weight(weightArray);
        RealMatrix matrix = weight.getWeight();

        // Verify dimensions
        assertEquals("Matrix dimension should be dim x dim", 3, matrix.getRowDimension());
        assertEquals("Matrix dimension should be dim x dim", 3, matrix.getColumnDimension());

        // Verify diagonal elements
        for (int i = 0; i < weightArray.length; i++) {
            assertEquals("Diagonal element at " + i + " should match input", weightArray[i], matrix.getEntry(i, i), 1e-10);
        }

        // Verify off-diagonal elements are zero
        for (int i = 0; i < matrix.getRowDimension(); i++) {
            for (int j = 0; j < matrix.getColumnDimension(); j++) {
                if (i != j) {
                    assertEquals("Off-diagonal element at (" + i + "," + j + ") should be 0", 0.0, matrix.getEntry(i, j), 1e-10);
                }
            }
        }
    }

    @Test
    public void testWeightConstructorWithSingleElement() {
        double[] weightArray = {5.0};
        Weight weight = new Weight(weightArray);
        RealMatrix matrix = weight.getWeight();

        assertEquals(1, matrix.getRowDimension());
        assertEquals(5.0, matrix.getEntry(0, 0), 1e-10);
    }

    @Test
    public void testWeightConstructorWithEmptyArray() {
        double[] weightArray = new double[0];
        Weight weight = new Weight(weightArray);
        RealMatrix matrix = weight.getWeight();

        assertEquals(0, matrix.getRowDimension());
        assertEquals(0, matrix.getColumnDimension());
    }

    @Test
    public void testWeightConstructorWithMatrix() {
        double[][] data = {
            {1.0, 0.5},
            {0.5, 1.0}
        };
        RealMatrix matrix = MatrixUtils.createRealMatrix(data);
        Weight weight = new Weight(matrix);

        RealMatrix retrievedMatrix = weight.getWeight();
        assertEquals(2, retrievedMatrix.getRowDimension());
        assertEquals(1.0, retrievedMatrix.getEntry(0, 0), 1e-10);
        assertEquals(0.5, retrievedMatrix.getEntry(0, 1), 1e-10);
        assertEquals(0.5, retrievedMatrix.getEntry(1, 0), 1e-10);
        assertEquals(1.0, retrievedMatrix.getEntry(1, 1), 1e-10);
    }
}
